@startuml

class Traveller {
  + Name : string
  + CompanyName : string
  + Address : string
  + BillingInformation : string
  + TravelPreferences : string[]
  + ReliabilityRating : float
}

class Hotel {
  + Name : string
  + Rating : int
}

class HotelChain {
  + Name : string
}

class City {
  + Name : string
}

class Address {
  + Street : string
  + City : string
}

class RoomType {
  + Type : string
}

class Booking {
  + BookingIdentifier : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MaxBudget : float
  + Status : string
  + CancellationDeadline : date
}

class SpecialOffer {
  + Price : float
  + CityArea : string
  + HotelRating : int
  + Preferences : string[]
}

class CreditCardInfo {
  + CardNumber : string
  + ExpiryDate : date
}

enum PaymentMethod {
  PRE_PAID
  PAID_AT_HOTEL
}

class HBMS {
  + CalculateReliability(Traveller) : float
}

Hotel "0..*" -- "0..1" HotelChain : is run by
Hotel "1" -- "1" Address : is located at
Hotel "1" -- "*" RoomType : offers
Hotel "1" -- "1" City : is in
Traveller "1" -- "*" Booking : makes
Traveller "1" -- "1" CreditCardInfo : provides
Booking "1" -- "1" PaymentMethod : is
Booking "1" -- "0..1" Hotel : is confirmed by
Booking "0..*" -- "1" Traveller : belongs to
SpecialOffer "*" -- "1" Booking : is offered for
SpecialOffer "*" -- "1" Hotel : provided by
HBMS "1" -- "*" Booking : manages
HBMS "1" -- "*" SpecialOffer : manages
HBMS "1" -- "*" Traveller : manages

@enduml

